def test_override_int(self):
    cfg = load_config({"port": 80, "host": "x"}, {"APP_PORT": "8080"})
    self.assertEqual(cfg["port"], 8080)
    self.assertEqual(cfg["host"], "x")

def test_override_float(self):
    cfg = load_config({"ratio": 0.5}, {"APP_RATIO": "1.25"})
    self.assertEqual(cfg["ratio"], 1.25)
    self.assertIsInstance(cfg["ratio"], float)

def test_override_bool(self):
    cfg = load_config({"debug": False}, {"APP_DEBUG": "true"})
    self.assertIs(cfg["debug"], True)
    cfg = load_config({"debug": True}, {"APP_DEBUG": "0"})
    self.assertIs(cfg["debug"], False)

def test_override_str(self):
    cfg = load_config({"host": "x"}, {"APP_HOST": "example.com"})
    self.assertEqual(cfg["host"], "example.com")

def test_non_app_env_ignored(self):
    cfg = load_config({"port": 80}, {"PORT": "9090", "PATH": "/bin"})
    self.assertEqual(cfg["port"], 80)

def test_unknown_key_ignored(self):
    cfg = load_config({"port": 80}, {"APP_TIMEOUT": "30"})
    self.assertEqual(cfg, {"port": 80})

def test_defaults_not_mutated(self):
    defaults = {"port": 80}
    load_config(defaults, {"APP_PORT": "8080"})
    self.assertEqual(defaults, {"port": 80})
